from cfg.loader import load_config

# Basic test
env = {'APP_DEBUG': 'True', 'APP_PORT': '8080', 'APP_HOST': 'localhost'}
defaults = {'debug': False, 'port': 80, 'host': '0.0.0.0'}
config = load_config(defaults, env)
assert config == {'debug': True, 'port': 8080, 'host': 'localhost'}
assert isinstance(config['debug'], bool)
assert isinstance(config['port'], int)
assert isinstance(config['host'], str)

# Test that non-APP_ keys are ignored
env2 = {'OTHER': 'value', 'APP_KEY': '42'}
defaults2 = {'key': 0}
config2 = load_config(defaults2, env2)
assert config2 == {'key': 42}

# Test that missing keys in defaults are not added
env3 = {'APP_MISSING': 'value'}
defaults3 = {'existing': 'default'}
config3 = load_config(defaults3, env3)
assert config3 == {'existing': 'default'}

# Test float coercion
env4 = {'APP_RATIO': '0.5'}
defaults4 = {'ratio': 0.0}
config4 = load_config(defaults4, env4)
assert config4 == {'ratio': 0.5}
assert isinstance(config4['ratio'], float)

print('All edge cases passed!')
"
